describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow("upToGrams must be a positive integer");
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow("costCents must be a non-negative integer");
    });

    it("rejects non-integer bracket values", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 100 },
          ]),
      ).toThrow("upToGrams must be a positive integer");
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: 1.5 },
          ]),
      ).toThrow("costCents must be a non-negative integer");
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow("overflowCostCents must be a non-negative integer");
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            5.5,
          ),
      ).toThrow("overflowCostCents must be a non-negative integer");
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 500, costCents: 300 }, // out of order to test sorting
        { upToGrams: 2000, costCents: 800 },
      ],
      1200,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for zero-weight items", () => {
      expect(
        calc.computeShippingCents([noWeightLine("a", 3)], 5000),
      ).toBe(0);
    });

    it("selects correct bracket for weight at boundary", () => {
      // 500g exactly → first bracket (500g) → 300
      expect(calc.computeShippingCents([line("a", 500, 1)], 5000)).toBe(300);
    });

    it("selects correct bracket for weight within range", () => {
      // 250g → within first bracket (up to 500) → 300
      expect(calc.computeShippingCents([line("a", 250, 1)], 5000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      // 501g → second bracket (up to 1000) → 500
      expect(calc.computeShippingCents([line("a", 501, 1)], 5000)).toBe(500);
    });

    it("selects highest bracket at its boundary", () => {
      // 2000g → third bracket (up to 2000) → 800
      expect(calc.computeShippingCents([line("a", 2000, 1)], 5000)).toBe(800);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      // 2001g → overflow → 1200
      expect(calc.computeShippingCents([line("a", 2001, 1)], 5000)).toBe(1200);
    });

    it("defaults overflow to heaviest bracket cost", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      // 1500g → overflow, no overflowCostCents → last bracket's 500
      expect(
        noOverflow.computeShippingCents([line("a", 1500, 1)], 5000),
      ).toBe(500);
    });

    it("sums weight across multiple lines", () => {
      // line a: 400g * 2 = 800g; line b: 300g * 1 = 300g; total = 1100g
      // 1100g > 1000g bracket, ≤ 2000g bracket → 800
      expect(
        calc.computeShippingCents(
          [line("a", 400, 2), line("b", 300, 1)],
          5000,
        ),
      ).toBe(800);
    });
  });
});

