      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(999),
    };

    await refreshPrices(lines, fetcher);
    expect(lines[0]!.product.unitPriceCents).toBe(100);
  });

  it("preserves other product fields", async () => {
    const lines: CartLine[] = [
      {
        product: {
          id: "a",
          name: "A",
          unitPriceCents: 100,
          weightGrams: 500,
          currency: "EUR",
        },
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(200),
    };

    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.currency).toBe("EUR");
  });

  it("throws RangeError for negative price", async () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer price", async () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };

    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("fetch failed");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };

    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import {
  InventoryError,
  type InventoryChecker,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { AsyncTaxRateProvider, TaxCalculator } from "../src/tax.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product } from "../src/product.ts";

const mkProduct = (
  id: string,
  unitPriceCents: number,
  opts?: Partial<Product>,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents,
  ...opts,
});

describe("Cart", () => {
  describe("add", () => {
    it("adds a new product", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding same product twice", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.add(mkProduct("a", 1000), 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(mkProduct("a", 1000), 0)).toThrow(RangeError);
      expect(() => cart.add(mkProduct("a", 1000), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(mkProduct("a", 1000), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity for existing product", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);
      expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.add(mkProduct("b", 500), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns deep copy that does not affect cart state", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      snap[0]!.product.unitPriceCents = 1;
      expect(cart.totals().subtotalCents).toBe(2000);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      cart.add(mkProduct("b", 500), 3);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(3500);
    });

    it("empty cart has all-zero totals", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });

    it("applies discount policy and clamps to [0, subtotal]", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(500);
      expect(t.totalCents).toBe(500); // 1000 - 500
    });

    it("clamps discount that exceeds subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(9999),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(1000); // clamped to subtotal
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-500),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn((taxable: number) =>
          Math.floor(taxable * 0.1),
        ),
      };
      const cart = new Cart({ discountPolicy, taxCalculator });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      // subtotal=1000, discount=200, discounted=800, tax=80
      expect(t.taxCents).toBe(80);
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US");
    });

    it("uses configured region for tax", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(50),
      };
      const cart = new Cart({ taxCalculator, region: "FR" });
      cart.add(mkProduct("a", 1000), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
    });

    it("computes shipping on discounted subtotal with lines", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy, shippingCalculator });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      expect(t.shippingCents).toBe(500);
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800, // discounted subtotal
      );
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(mkProduct("a", 1000), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(mkProduct("a", 1000), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("totalCents = discountedSubtotal + tax + shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
      });
      cart.add(mkProduct("a", 1000), 1);
      const t = cart.totals();
      // subtotal=1000, discount=100, discounted=900, tax=80, shipping=500
      expect(t.totalCents).toBe(900 + 80 + 500);
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without collaborators", async () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0]!.quantity).toBe(2);
    });

    it("refreshes prices via priceFetcher", async () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(result.totals.subtotalCents).toBe(1500);
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("throws InventoryError when item unavailable", async () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          reason: "discontinued",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(5);
        expect(invErr.message).toBe("discontinued");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const cart = new Cart();
      cart.add(mkProduct("a", 1000), 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.unreachable("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const invErr = err as InventoryError;
        expect(invErr.productId).toBe("a");
        expect(invErr.requested).toBe(10);
        expect(invErr.available).toBe(3);
