      [1000, 500, 500], // capped: discount > subtotal
      [500, 500, 500], // exact match
      [500, 0, 0], // zero subtotal
      [500, -100, 0], // negative subtotal
      [0, 1000, 0], // zero discount
    ])("$%i off on %i cents = %i", (amount, subtotal, expected) => {
