import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [999999, 0],
    [-500, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(msg);
    });

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      // [percent, subtotal, expected]
      [10, 1000, 100],
      [10, 999, 99], // floor(999 * 10 / 100) = 99
      [50, 1001, 500], // floor(1001 * 50 / 100) = 500
      [100, 5000, 5000],
      [0, 5000, 0],
      [33, 100, 33],
      [33, 10, 3], // floor(10 * 33 / 100) = 3
    ])("%i%% of %i cents = %i", (percent, subtotal, expected) => {
      const policy = new PercentageDiscountPolicy(percent);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "non-negative integer"],
      [10.5, "non-negative integer"],
      [NaN, "non-negative integer"],
    ])("rejects invalid amountCents %s", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it.each([0, 100, 99999])("accepts valid amountCents %i", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      // [amount, subtotal, expected]
      [500, 1000, 500], // normal: discount < subtotal
      [1000, 500, 500], // capped: discount > subtotal
      [500, 500, 500], // exact match
      [500, 0, 0], // zero subtotal
      [500, -100, 0], // negative subtotal
      [0, 1000, 0], // zero discount
    ])("$%i off on %i cents = %i", (amount, subtotal, expected) => {
      const policy = new FixedAmountDiscountPolicy(amount);
      expect(policy.computeDiscountCents(subtotal)).toBe(expected);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      // 10% of 1000 = 100; fixed 200 = 200; sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("can exceed subtotal (Cart.totals clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(80), // 800
          new FixedAmountDiscountPolicy(500), // 500
        ],
        "sum",
      );
      // 80% of 1000 = 800 + 500 = 1300 > 1000 (clamped by Cart, not by Composite)
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500)],
        "sum",
      );
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps individual negative results to 0 before summing", () => {
      // NoDiscountPolicy returns 0, which is ≥ 0, but if a custom policy
      // returned a negative, Math.max(0, ...) should clamp it
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // max(0, -100) + max(0, min(200, 1000)) = 0 + 200 = 200
      expect(composite.computeDiscountCents(1000)).toBe(200);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100; remaining = 900
          new PercentageDiscountPolicy(10), // 10% of 900 = 90; remaining = 810
        ],
        "chain",
      );
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      // Fixed 200 first, then 10% of remaining
      const a = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200), // 200 off; remaining = 800
          new PercentageDiscountPolicy(10), // 10% of 800 = 80
        ],
        "chain",
      );
      // 10% first, then fixed 200
      const b = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 10% of 1000 = 100; remaining = 900
          new FixedAmountDiscountPolicy(200), // min(200, 900) = 200
        ],
        "chain",
      );
